# -*- coding: utf-8 -*-
# Catechism bank — Molla Jāmī's Q&A on the Kāfiya (research/sources/molla-cami-sual-cevap.txt, Ottoman), part 1: the
# word, the sentence and the iʿrāb, items 1–29. The Arabic is the sharḥ's own (vowelled in the notebook); the Turkish is the
# notebook's answer in today's spelling; the English is ours.
ITEMS = [
 {"n": 1, "q": {"tr": "Nahiv ilminin tarifi, mevzuu ve gayesi nedir?", "en": "How is the science of naḥw defined, and what are its subject and its aim?"},
  "a": {"tr": "Tarifi: i'rab ve binâ bakımından Arapça kelimenin hallerinin kendisiyle bilindiği ilimdir. Gayesi: i'rab ve binâda hatadan sakınmaktır. Mevzuu: i'rab ve binâ bakımından kelâmda vâki olan Arapça kelime — yani kelime ve kelâmdır.", "en": "A science by which the states of the Arabic word are known with respect to iʿrāb and bināʾ. Its aim: guarding against error in iʿrāb and bināʾ. Its subject: the Arabic word as it occurs in speech, with respect to iʿrāb and bināʾ — the word and the sentence."},
  "ar": ["عِلْمٌ يُعْرَفُ بِهِ أَحْوَالُ الْكَلِمَةِ الْعَرَبِيَّةِ مِنْ حَيْثُ الْإِعْرَابُ وَالْبِنَاءُ", "الِاحْتِرَازُ عَنِ الْخَطَإِ فِي الْإِعْرَابِ وَالْبِنَاءِ"], "notes": ["tarifat-daftar-al-kafiya", "al-kalima-wal-kalam"]},
 {"n": 2, "q": {"tr": "İbn Hâcib hazretleri niçin kitabına hamdele ile başlatmadı?", "en": "Why did Ibn al-Ḥājib not open his book with the ḥamdala?"},
  "a": {"tr": "Nefsini kırmak için: kitabının kendi kitabı olması haysiyetiyle selefin kitapları gibi olmadığını düşünerek, onu selefin âdeti üzere (besmele, hamdele, salvele ile) başlatmadı. Bundan kitabının bereketten kesik olması lâzım gelmez; hamdeleyi kitabından bir cüz kılmadan zikretmesi de câizdir.", "en": "Out of humility: holding that a book of his own was not like the books of the early masters, he did not open it by their custom (basmala, ḥamdala, ṣalwala). It does not follow that the book is cut off from blessing; he may have said the ḥamdala without making it part of the book."},
  "ar": ["الْحَمْدَلَةُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 3, "q": {"tr": "Kâfiye kitabının musannifi kimdir? «Kâfiye» ne kelimedir?", "en": "Who wrote the Kāfiya, and what kind of word is «Kāfiya»?"},
  "a": {"tr": "Musannifi İbn Hâcib hazretleridir. «Kâfiye» kelimesi sülâsî mücerredin ikinci bâbından ism-i fâil müfred müennestir: كَفَى يَكْفِي فَهُوَ كَافٍ; ism-i fâilin çekilişi كَافٍ – كَافِيَةٌ.", "en": "Ibn al-Ḥājib. «Kāfiya» is the feminine singular ism fāʿil of the second bāb of the bare triliteral: كَفَى يَكْفِي فَهُوَ كَافٍ; its ism fāʿil runs كَافٍ – كَافِيَةٌ."},
  "ar": ["كَفَى يَكْفِي فَهُوَ كَافٍ"], "notes": ["al-kalima-wal-kalam", "ism-maqsur-manqus"]},
 {"n": 4, "q": {"tr": "Musannif hazretleri kitabını niçin kelime ve kelâmın tarifleriyle başlatmıştır?", "en": "Why did the author open his book with the definitions of the word and the sentence?"},
  "a": {"tr": "Çünkü bu kitapta kelime ve kelâmın hallerinden bahsetmektedir; kelime ve kelâmın tarifleri bilinmeden hallerinden bahsetmek mümkün değildir.", "en": "Because the book treats the states of the word and the sentence, and their states cannot be treated before their definitions are known."},
  "ar": ["الْكَلِمَةُ وَالْكَلَامُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 5, "q": {"tr": "Musannif hazretleri kitabında niçin kelimeyi kelâm üzerine takdim etti?", "en": "Why did the author put the word before the sentence?"},
  "a": {"tr": "Kelimenin fertleri kelâmın fertlerinden, kelimenin mefhumu kelâmın mefhumundan bir cüz olduğu için.", "en": "Because the word's instances are parts of the sentence's instances, and the word's concept a part of the sentence's concept."},
  "ar": ["الْكَلِمَةُ جُزْءُ الْكَلَامِ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 6, "q": {"tr": "Kelimenin tarifi nedir? «Kelime» ve «kelâm» neden müştaktır? Delil nedir?", "en": "How is the word defined? From what are «kalima» and «kalām» derived, and what is the proof?"},
  "a": {"tr": "Kelime: müfred bir mânâ için vaz olunan lafızdır. Kelime ve kelâm, «cerh» (yaralama) mânâsına olan كَلْم masdarından müştaktır; delili şu şiirdir: جِرَاحَاتُ السِّنَانِ لَهَا الْتِيَامٌ • وَلَا يَلْتَامُ مَا جَرَحَ اللِّسَانُ.", "en": "The word is an utterance coined for a single meaning. «Kalima» and «kalām» derive from the maṣdar كَلْم, «wounding»; the proof is the verse جِرَاحَاتُ السِّنَانِ لَهَا الْتِيَامٌ • وَلَا يَلْتَامُ مَا جَرَحَ اللِّسَانُ."},
  "ar": ["لَفْظٌ وُضِعَ لِمَعْنًى مُفْرَدٍ", "جِرَاحَاتُ السِّنَانِ لَهَا الْتِيَامٌ وَلَا يَلْتَامُ مَا جَرَحَ اللِّسَانُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 7, "q": {"tr": "«الْكَلِمَة» lafzındaki lâm ve tâ niçindir?", "en": "What are the lām and the tāʾ of «الْكَلِمَة» for?"},
  "a": {"tr": "Lâm cins içindir; tâ vahdet içindir.", "en": "The lām is for the genus; the tāʾ for the unit."},
  "ar": ["الْكَلِمَةُ"], "notes": ["al-kalima-wal-kalam", "anwa-al-lam-al-tarif"]},
 {"n": 8, "q": {"tr": "Lafzın lügavî ve ıstılâhî tarifi nedir? Lafız kaç kısımdır?", "en": "How is «lafẓ» defined in the language and as a term, and how many kinds has it?"},
  "a": {"tr": "Lügatte الرَّمْيُ (atmak). Istılahta: müfred veya mürekkeb, mevzû veya mühmel olsun, insanın hakikaten veya hükmen telaffuz ettiği şeydir. İki kısımdır: hakikî lafız — harf ve ses cinsinden olup insanın telaffuz ettiği (زَيْدٌ، ضَرَبَ); hükmî lafız — harf ve ses cinsinden olmayıp niyette olan (اِضْرِبْ'in altındaki أَنْتَ, ضَرَبَ'nin altındaki هُوَ).", "en": "In the language, «casting». As a term: what a human utters, in fact or in ruling, whether single or compound, coined or meaningless. Two kinds: the real utterance, of the genus of letters and sound (زَيْدٌ، ضَرَبَ); and the utterance in ruling, which is in the intention only — the أَنْتَ under اِضْرِبْ, the هُوَ under ضَرَبَ."},
  "ar": ["مَا يَتَلَفَّظُ بِهِ الْإِنْسَانُ حَقِيقَةً أَوْ حُكْمًا مُهْمَلًا كَانَ أَوْ مَوْضُوعًا مُفْرَدًا كَانَ أَوْ مُرَكَّبًا"], "notes": ["al-kalima-wal-kalam", "tarifat-daftar-al-kafiya"]},
 {"n": 9, "q": {"tr": "Mahzuflar, Allah Teâlâ'nın kelâm-ı lafzîsi, meleklerin ve cinlerin kelimeleri ve devâll-i erbaa lafzın tarifine dâhil midir?", "en": "Do dropped words, God's spoken word, the words of angels and jinn, and the four non-verbal signs fall under the definition of «lafẓ»?"},
  "a": {"tr": "Mahzuflar, kelâm-ı lafzî ve meleklerin ve cinlerin kelimeleri bazı vakitlerde insanlar tarafından telaffuz olunduğu için lafzın tarifine dâhildir ve hakikî kısmındandır. Devâll-i erbaa ise insanlar tarafından telaffuz olunmadığı için dâhil değildir.", "en": "The dropped, God's spoken word and the words of angels and jinn are sometimes uttered by humans, so they fall under it, in its real kind. The four signs are not uttered by humans and do not."},
  "ar": ["الدَّوَالُّ الْأَرْبَعُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 10, "q": {"tr": "Devâll-i erbaa ne demektir ve nelerdir?", "en": "What are the «four signifiers»?"},
  "a": {"tr": "Dört delâlet edici şey: hutût (yazılar), ukûd (düğümler), işârât (işaretler), nusub (dikili taşlar). İnsanlar tarafından telaffuz olunmadıkları için lafzın tarifine dâhil değildirler.", "en": "Four things that signify: writing, knots, gestures and standing stones. Not being uttered, they fall outside the definition of «lafẓ»."},
  "ar": ["الْخُطُوطُ وَالْعُقُودُ وَالْإِشَارَاتُ وَالنُّصُبُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 11, "q": {"tr": "Vaz'ın tarifi nedir?", "en": "How is coinage (waḍʿ) defined?"},
  "a": {"tr": "Bir şeyi bir şeye tahsis etmektir ki, birinci şey hissedildiği veya ıtlak edildiği zaman ondan ikinci şey anlaşılır.", "en": "Appointing one thing to another so that, whenever the first is uttered or sensed, the second is understood from it."},
  "ar": ["تَخْصِيصُ شَيْءٍ بِشَيْءٍ بِحَيْثُ مَتَى أُطْلِقَ أَوْ أُحِسَّ الشَّيْءُ الْأَوَّلُ فُهِمَ مِنْهُ الشَّيْءُ الثَّانِي"], "notes": ["tarifat-daftar-al-kafiya", "al-kalima-wal-kalam"]},
 {"n": 12, "q": {"tr": "Mânânın tarifi nedir? «مَعْنًى» lafzı ne kelimedir?", "en": "How is «maʿnā» defined, and what kind of word is it?"},
  "a": {"tr": "Mânâ: bir şeyle kastolunandır. «مَعْنًى» lafzı ya sülâsî mücerredin ikinci bâbından (عَنَى يَعْنِي) مَفْعَل vezninde «maksad» mânâsına ism-i mekân, ya mef'ûl mânâsına masdar-ı mîmî, yahut مَرْمِيٌّ gibi مَعْنِيٌّ'den hafifletilmiş ism-i mef'ûldür.", "en": "«What is meant by a thing.» The word is either a place-noun on مَفْعَل from the second bāb (عَنَى يَعْنِي) meaning «aim», or a mīmī maṣdar in the sense of the mafʿūl, or an ism mafʿūl lightened from مَعْنِيٌّ like مَرْمِيٌّ."},
  "ar": ["مَا يُقْصَدُ بِشَيْءٍ"], "notes": ["tarifat-daftar-al-kafiya", "al-kalima-wal-kalam"]},
 {"n": 13, "q": {"tr": "Müfredin tarifi nedir?", "en": "How is the single word (mufrad) defined?"},
  "a": {"tr": "Lafzının cüz'ü, mânâsının cüz'üne delâlet etmeyendir.", "en": "That no part of whose utterance signifies a part of its meaning."},
  "ar": ["مَا لَا يَدُلُّ جُزْءُ لَفْظِهِ عَلَى جُزْءِ مَعْنَاهُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 14, "q": {"tr": "Nahiv ilminde «müfred» lafzı kaç mânâda kullanılır?", "en": "In how many senses is «mufrad» used in naḥw?"},
  "a": {"tr": "Beş: mürekkebin, tesniye ve cem'in, cümlenin, muzâf ve şibh-i muzâfın ve nisbetin karşılığı olarak.", "en": "Five: as the opposite of the compound, of the dual and plural, of the sentence, of the annexed and quasi-annexed, and of the nisba."},
  "ar": ["الْمُفْرَدُ فِي عِلْمِ النَّحْوِ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 15, "q": {"tr": "Arap kelâmında kaç kısım terkib vardır? Hangisinden kelâm hâsıl olur?", "en": "How many kinds of compound are there in Arabic, and from which does a sentence arise?"},
  "a": {"tr": "Altı: isnâdî (زَيْدٌ قَائِمٌ), izâfî (غُلَامُ زَيْدٍ), ta'dâdî (خَمْسَةَ عَشَرَ), tavsîfî (رَجُلٌ عَالِمٌ), savtî (سِيبَوَيْهِ), mezcî (بَعْلَبَكَّ). Yalnız terkib-i isnâdîden kelâm hâsıl olur.", "en": "Six: predicative (زَيْدٌ قَائِمٌ), annexational (غُلَامُ زَيْدٍ), numerical (خَمْسَةَ عَشَرَ), descriptive (رَجُلٌ عَالِمٌ), of sound (سِيبَوَيْهِ), of fusion (بَعْلَبَكَّ). Only the predicative yields a sentence."},
  "ar": ["بَعْلَبَكَّ", "خَمْسَةَ عَشَرَ", "زَيْدٌ قَائِمٌ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 16, "q": {"tr": "Delâletin tarifi nedir? Delâlet vaz'ı mı, yoksa vaz' delâleti mi îcab ettirir?", "en": "How is signification defined? Does it entail coinage, or coinage it?"},
  "a": {"tr": "Delâlet: bir şeyin, kendisinden başka bir şey anlaşılacak halde olmasıdır. Vaz' delâleti îcab ettirir; delâlet vaz'ı îcab ettirmez.", "en": "A thing's being such that another thing is understood from it. Coinage entails signification; signification does not entail coinage."},
  "ar": ["كَوْنُ الشَّيْءِ بِحَيْثُ يُفْهَمُ مِنْهُ شَيْءٌ آخَرُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 17, "q": {"tr": "Kelimenin kısımları nelerdir? Neden üç kısma münhasırdır?", "en": "What are the kinds of word, and why only three?"},
  "a": {"tr": "İsim, fiil, harf. Kelime ya kendi nefsinde bir mânâya delâlet eder ya etmez; etmeyen harftir. Eden ya üç zamandan birine yakın olur ya olmaz: olan fiil, olmayan isimdir.", "en": "The noun, the verb and the particle. A word either signifies a meaning in itself or not; the latter is the particle. One that does is either tied to one of the three times or not: the former is the verb, the latter the noun."},
  "ar": ["الْكَلِمَةُ اسْمٌ وَفِعْلٌ وَحَرْفٌ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 18, "q": {"tr": "«İsim» lafzı ne kelimedir?", "en": "From what is the word «ism» derived?"},
  "a": {"tr": "Basralılara göre «yükseklik» mânâsına gelen سُمُوّ masdarından (سَمَا يَسْمُو): kelâm yalnız isimden hâsıl olup fiil ve harften hâsıl olmadığı için isim onlardan üstündür. Kûfelilere göre «alâmet» mânâsına gelen وَسْم veya سِمَة'den: isim, müsemmâsı üzerine bir alâmettir.", "en": "For the Baṣrans from سُمُوّ, «height» (سَمَا يَسْمُو): a sentence arises from nouns alone and not from verbs and particles, so the noun stands above them. For the Kūfans from وَسْم or سِمَة, «mark»: the noun is a mark upon what it names."},
  "ar": ["السُّمُوُّ", "الْوَسْمُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 19, "q": {"tr": "İsim, fiil ve harften her biri diğerlerinden ne ile ayrılır?", "en": "By what is each of the noun, the verb and the particle told from the others?"},
  "a": {"tr": "Harf, kendi nefsinde bir mânâya delâlet etmemekle fiil ve isimden ayrılır. Fiil, kendi nefsinde bir mânâya delâlet etmekle harften, üç zamandan birine yakın olmakla isimden ayrılır. İsim, kendi nefsinde bir mânâya delâlet etmekle harften, üç zamandan birine yakın olmamakla fiilden ayrılır.", "en": "The particle, by not signifying in itself; the verb, by signifying in itself (from the particle) and by being tied to a time (from the noun); the noun, by signifying in itself (from the particle) and by not being tied to a time (from the verb)."},
  "ar": ["الِاسْمُ وَالْفِعْلُ وَالْحَرْفُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 20, "q": {"tr": "Kelâmın lügavî ve ıstılâhî tarifleri nedir?", "en": "How is «kalām» defined in the language and as a term?"},
  "a": {"tr": "Lügatte: az veya çok, kendisiyle konuşulandır. Istılahta: isnad ile iki kelimeyi tazammun edendir.", "en": "In the language: what one speaks with, little or much. As a term: what contains two words with predication."},
  "ar": ["مَا يُتَكَلَّمُ بِهِ قَلِيلًا كَانَ أَوْ كَثِيرًا", "مَا تَضَمَّنَ كَلِمَتَيْنِ بِالْإِسْنَادِ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 21, "q": {"tr": "İsnadın tarifi nedir?", "en": "How is predication (isnād) defined?"},
  "a": {"tr": "Muhâtaba, üzerine sükût sahih olan tam bir fayda ifade edecek şekilde, hakikaten veya hükmen iki kelimeden birini diğerine nisbet etmektir.", "en": "Relating one of two words, in fact or in ruling, to the other so that the hearer gains a complete benefit upon which silence is sound."},
  "ar": ["نِسْبَةُ إِحْدَى الْكَلِمَتَيْنِ حَقِيقَةً أَوْ حُكْمًا إِلَى الْأُخْرَى بِحَيْثُ يُفِيدُ الْمُخَاطَبَ فَائِدَةً تَامَّةً يَصِحُّ السُّكُوتُ عَلَيْهَا"], "notes": ["al-kalima-wal-kalam", "tarifat-daftar-al-kafiya"]},
 {"n": 22, "q": {"tr": "Kelâm nelerden hâsıl olur? Niçin?", "en": "From what does a sentence arise, and why?"},
  "a": {"tr": "İki isimden veya bir isim ile bir fiilden. Çünkü kelâm için isnad, isnad için bir müsned ve bir müsnedün ileyh lâzımdır. İsimler hem müsned hem müsnedün ileyh olabildiğinden iki isimden kelâm hâsıl olur; fiiller yalnız müsned olduğundan müsnedün ileyh olan bir isimle birleşince kelâm olur; harfler ne müsned ne müsnedün ileyh olur. Bu yüzden iki fiilden, iki harften, fiil ile harften ve isim ile harften kelâm hâsıl olmaz.", "en": "From two nouns, or a noun and a verb. A sentence needs predication; predication needs a predicate and a subject. Nouns can be either, so two nouns make a sentence; verbs are predicates only, so a verb with a noun subject does; particles are neither. Hence two verbs, two particles, a verb and a particle, or a noun and a particle make none."},
  "ar": ["الْمُسْنَدُ وَالْمُسْنَدُ إِلَيْهِ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 23, "q": {"tr": "İsmin tarifi nedir? Hususiyetleri nelerdir?", "en": "How is the noun defined, and what are its marks?"},
  "a": {"tr": "Üç zamandan birine yakın olmayıp kendi nefsinde bir mânâya delâlet eden kelimedir. Hususiyetleri: lâm-ı ta'rifin, cerrin ve tenvinin dâhil olması; müsnedün ileyh olması; izâfe olması (harf-i cer takdiriyle bir şeye muzâf olması).", "en": "What signifies a meaning in itself without being tied to one of the three times. Its marks: the article, jarr and tanwīn enter upon it; it is a subject; it is annexed, with a jarr letter implied."},
  "ar": ["مَا دَلَّ عَلَى مَعْنًى فِي نَفْسِهِ غَيْرِ مُقْتَرِنٍ بِأَحَدِ الْأَزْمِنَةِ الثَّلَاثَةِ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 24, "q": {"tr": "İsim kaç kısımdır? Mu'reb nedir? Hükmü nedir?", "en": "How many kinds of noun are there? What is the declinable noun, and what is its ruling?"},
  "a": {"tr": "İki: mu'reb ve mebnî. Mu'reb: mebnî-i asla benzemeyen mürekkeb isimdir. Hükmü: âmillerin amelde ihtilâfı sebebiyle âhirinin lafzan veya takdiren değişmesidir — hareke ile lafzan (جَاءَنِي زَيْدٌ، رَأَيْتُ زَيْدًا، مَرَرْتُ بِزَيْدٍ), harf ile lafzan (أَبُوهُ، أَبَاهُ، أَبِيهِ), hareke ile takdiren (فَتًى), harf ile takdiren (أَبُو الْقَاسِمِ، أَبَا الْقَاسِمِ، أَبِي الْقَاسِمِ).", "en": "Two: declinable and built. The declinable: the compounded noun that does not resemble the originally built. Its ruling: its end changes, in wording or by estimation, as the governors differ — by a vowel in wording (جَاءَنِي زَيْدٌ، رَأَيْتُ زَيْدًا، مَرَرْتُ بِزَيْدٍ), by a letter in wording (أَبُوهُ، أَبَاهُ، أَبِيهِ), by a vowel estimated (فَتًى), by a letter estimated (أَبُو الْقَاسِمِ، أَبَا الْقَاسِمِ، أَبِي الْقَاسِمِ)."},
  "ar": ["الْمُرَكَّبُ الَّذِي لَمْ يُشْبِهْ مَبْنِيَّ الْأَصْلِ"], "notes": ["al-murab-wal-mabni-wal-irab"]},
 {"n": 25, "q": {"tr": "Mebnî-i asıllar kaçtır ve nelerdir?", "en": "How many originally built words are there, and which?"},
  "a": {"tr": "Dört: fiil-i mâzî, lâmsız emir, harf ve cümle.", "en": "Four: the māḍī, the lām-less imperative, the particle and the sentence."},
  "ar": ["مَبْنِيُّ الْأَصْلِ"], "notes": ["al-mabni-wal-mudmar", "al-murab-wal-mabni-wal-irab"]},
 {"n": 26, "q": {"tr": "İ'rabın tarifi nedir? Nevileri nelerdir? Ref', nasb ve cer neyin alâmetidir?", "en": "How is iʿrāb defined, what are its kinds, and what do rafʿ, naṣb and jarr mark?"},
  "a": {"tr": "İ'rab: mu'reb üzerine ârız olan mânâlara delâlet etsin diye, hareke veya harf sebebiyle mu'rebin âhirinin değişmesidir. Nevileri ref', nasb ve cer. Ref' fâiliyyetin, nasb mef'ûliyyetin, cer izâfetin alâmetidir.", "en": "What the declinable's end changes by, so as to signify the meanings that come upon it. Its kinds: rafʿ, naṣb, jarr. Rafʿ marks doer-ness, naṣb object-ness, jarr annexation."},
  "ar": ["مَا اخْتَلَفَ آخِرُهُ بِهِ لِيَدُلَّ عَلَى الْمَعَانِي الْمُعْتَوِرَةِ عَلَيْهِ"], "notes": ["al-murab-wal-mabni-wal-irab"]},
 {"n": 27, "q": {"tr": "Ref', nasb ve cer neye mahsus kılındı?", "en": "To what are rafʿ, naṣb and jarr confined?"},
  "a": {"tr": "İ'rabı hareke ve harf ile olanlara mahsus kılındı; binâsı hareke ile olanlarda kullanılmaz — zamme, fetha ve kesre ise çoğu kere mebnîlerde, az kere mu'reblerde kullanılır. Ayrıca ref' fâile, nasb mef'ûle mahsus kılındı: ref' ağırdır, fâil azdır; ağır olan aza verildi; nasb hafiftir, mef'ûl çoktur; hafif olan çoğa verildi. Muzâfun ileyh için cerden başka alâmet kalmayınca cer ona alâmet kılındı.", "en": "To words declined by vowel or letter; they are not used of words built on a vowel — while ḍamma, fatḥa and kasra are used mostly of built words and rarely of declinable ones. Rafʿ went to the doer and naṣb to the object: rafʿ is heavy and doers are few, so the heavy went to the few; naṣb is light and objects many, so the light went to the many. Jarr was left for the annexed-to."},
  "ar": ["الرَّفْعُ وَالنَّصْبُ وَالْجَرُّ"], "notes": ["al-murab-wal-mabni-wal-irab"]},
 {"n": 28, "q": {"tr": "Mu'rebin nevilerinin i'rabı nasıldır?", "en": "How are the kinds of declinable noun declined?"},
  "a": {"tr": "Müfred ve cem'-i mükesser-i munsarıf: zamme, fetha, kesre (زَيْدٌ، كُتُبٌ). Gayr-i munsarıf: zamme, fetha, fetha (أَحْمَدُ). Cem'-i müennes-i sâlim: zamme, kesre, kesre (مُسْلِمَاتٌ). Mütekellim yâ'sının gayrına muzâf müfred mükebber esmâ-i sitte: vâv, elif, yâ (أَبُوهُ، أَخُوهُ، حَمُوهَا، هَنُوهُ، فُوهُ، ذُو مَالٍ). Tesniye, اثْنَانِ ve zamire muzâf كِلَا: elif, yâ, yâ. Cem'-i müzekker-i sâlim, أُولُو، عِشْرُونَ ve kardeşleri: vâv, yâ, yâ.", "en": "Triptote singular and broken plural: ḍamma, fatḥa, kasra (زَيْدٌ، كُتُبٌ). Diptote: ḍamma, fatḥa, fatḥa (أَحْمَدُ). Sound feminine plural: ḍamma, kasra, kasra (مُسْلِمَاتٌ). The six nouns, singular, not diminutive, annexed to other than the speaker's yāʾ: wāw, alif, yāʾ (أَبُوهُ، أَخُوهُ، حَمُوهَا، هَنُوهُ، فُوهُ، ذُو مَالٍ). Dual, اثْنَانِ and كِلَا with a pronoun: alif, yāʾ, yāʾ. Sound masculine plural, أُولُو، عِشْرُونَ and its sisters: wāw, yāʾ, yāʾ."},
  "ar": ["أَبُوهُ أَخُوهُ حَمُوهَا هَنُوهُ فُوهُ ذُو مَالٍ"], "notes": ["al-murab-wal-mabni-wal-irab", "five-nouns", "naqis-al-irab-bil-harakat-wal-murab-bil-huruf"]},
 {"n": 29, "q": {"tr": "İ'rab-ı takdirî nerelerde olur?", "en": "Where is iʿrāb estimated?"},
  "a": {"tr": "İki yerde. İ'rabın mazur olduğu, yani lafızda zuhurunun mümteni olduğu mu'reb isimde — âhirinde elif-i maksûre olan (الْعَصَا) ve mütekellim yâ'sına muzâf olan (غُلَامِي). İ'rabın lafızda zuhurunun lisana ağır geldiği yerde — i'rabı hareke ile olan (قَاضٍ) ve harf ile olan (مُسْلِمِيَّ).", "en": "In two: where it is excused — its appearance impossible — in a noun ending in the shortened alif (الْعَصَا) or annexed to the speaker's yāʾ (غُلَامِي); and where its appearance would be heavy on the tongue — a noun declined by vowel (قَاضٍ) or by letter (مُسْلِمِيَّ)."},
  "ar": ["غُلَامِي", "قَاضٍ", "الْعَصَا"], "notes": ["al-murab-wal-mabni-wal-irab", "ism-maqsur-manqus", "ya-al-mutakallim"]},
]
